        edge) echo "edge" ;;
        0) echo "edge" ;;
        pure-edge) echo "edge" ;;
        standalone-edge) echo "edge" ;;
        mini) echo "mini" ;;
        1) echo "mini" ;;
        minimal) echo "mini" ;;
        4g) echo "mini" ;;
        standard) echo "standard" ;;
        2) echo "standard" ;;
        std) echo "standard" ;;
        16g) echo "standard" ;;
        full) echo "full" ;;
        3) echo "full" ;;
        complete) echo "full" ;;
        20g) echo "full" ;;
        *)
        printf '未知部署规格: %s\n' "${1:-${EASYAIOT_DEPLOY_PROFILE:-}}" >&2
        return 1
        ;;
    esac
}

